#include "scamptrie_dynamic.h"
#include "image_io.hpp"
#include <iostream>
#include <memory>
#include <stdexcept>
#include <vector>
#include <sys/wait.h>
#include <cstdlib>
int main(){
 try{
    std::ios::sync_with_stdio(false);std::cin.tie(nullptr);
    size_t cases;std::cin>>cases;std::cout<<"{\"results\":[";
    for(size_t c=0;c<cases;++c){
        if(c)std::cout<<',';auto live=std::unique_ptr<ScampTrieDynamic>(new ScampTrieDynamic());
        live->set_insert_prefix_timing_enabled(false);MemoryImage loaded;
        std::vector<nexthop_t> answers;std::vector<ImageData> saved;std::vector<bool> loads;
        size_t count;std::cin>>count;
        for(size_t i=0;i<count;++i){
            char op;std::cin>>op;
            if(op=='P'){auto ip=read_ip();unsigned len;uint64_t hop;std::cin>>len>>hop;
                if(live->insert_prefix(ip,len,hop)!=SCAMPTRIE_OK)throw std::runtime_error("put failed");}
            else if(op=='Q'||op=='I'){size_t n;std::cin>>n;for(size_t j=0;j<n;++j){auto ip=read_ip();uint32_t marker=0;answers.push_back(op=='Q'?live->lookup(ip,marker):loaded.lookup(ip));}}
            else if(op=='S'){auto exporter=std::unique_ptr<MemInit>(new MemInit(live.get()));saved.push_back(exporter->capture());}
            else if(op=='R'){size_t id;std::cin>>id;loads.push_back(loaded.load(saved.at(id)));}
            else if(op=='L'){auto d=image_read_wire();loads.push_back(loaded.load(d));}
            else throw std::runtime_error("wire opcode");
        }
        if(!std::cin)throw std::runtime_error("wire exhausted");
        std::cout<<"{\"answers\":[";for(size_t i=0;i<answers.size();++i){if(i)std::cout<<',';if(answers[i]==LPM_INVALID_NH)std::cout<<"null";else std::cout<<answers[i];}
        std::cout<<"],\"snapshots\":[";for(size_t i=0;i<saved.size();++i){if(i)std::cout<<',';image_write_json(saved[i]);}
        std::cout<<"],\"loads\":[";for(size_t i=0;i<loads.size();++i){if(i)std::cout<<',';std::cout<<(loads[i]?"true":"false");}std::cout<<"]}";
    }
    std::cout<<"]}\n";
    if(const char* feed=std::getenv("SCAMP_FEED_PID")){int status;waitpid(std::strtol(feed,nullptr,10),&status,0);}
    return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}
